    "id": "case-108-dark-mode-marketing-case-study-ui",
    "title": "Dark Mode Marketing Case Study UI",
    "category": "Ad Creative Cases",
    "author": "@IndieDevHailey",
    "authorUrl": "https://x.com/IndieDevHailey",
    "sourceUrl": "https://x.com/IndieDevHailey/status/2044974254769463312",
    "imageUrl": "/api/gallery-image/images/poster_case108/output.jpg",
